package cn.mop.api;

import cn.mop.domain.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AssetLedgerReadControllerTest {
    static final String ACTOR="55000000-0000-4000-8000-000000000001",TENANT="55000000-0000-4000-8000-000000000011",OTHER="55000000-0000-4000-8000-000000000012";
    PlatformRepository repository;PlatformController controller;
    @BeforeEach void setup(){repository=mock(PlatformRepository.class);controller=new PlatformController(repository,new ObjectMapper(),null,null,null);when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"msp",7,true)));when(repository.user(ACTOR)).thenReturn(Optional.of(new FixtureUser(ACTOR,"Synthetic","msp")));when(repository.tenant(TENANT)).thenReturn(new Tenant(TENANT,"Synthetic tenant"));when(repository.metadata()).thenReturn(new RepositoryMetadata("remote_test","postgresql",true,"test_oidc"));}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/assets");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-ledger");return r;}
    Asset asset(int n){return new Asset(String.format("55000000-0000-4000-8000-%012x",100+n),TENANT,"Asset "+n,"router","192.0.2.1","site-a","unknown","DRAFT","manual",null,"NOT_ONBOARDED",1,Instant.EPOCH.plusMillis(n),Instant.EPOCH.plusMillis(n),"UNKNOWN","PENDING_ONBOARDING");}
    Map<?,?> data(Object response){return (Map<?,?>)((Map<?,?>)response).get("data");}
    String firstCursor(){var rows=java.util.stream.IntStream.rangeClosed(1,11).mapToObj(this::asset).toList();when(repository.authorizedAssets(eq(TENANT),eq(ACTOR),eq(7L),any())).thenReturn(rows);var r=request();r.addParameter("page_size","10");return (String)data(controller.assets(Map.of("page_size","10"),r)).get("next_cursor");}
    @Test void controllerUsesBoundedRepositoryLookaheadAndSignedCursorWithoutUnboundedFallback(){var query=new AssetReadQuery("router","unknown","site-a","literal%_",11,null,null);var rows=java.util.stream.IntStream.rangeClosed(1,11).mapToObj(this::asset).toList();when(repository.authorizedAssets(TENANT,ACTOR,7,query)).thenReturn(rows);var r=request();r.addHeader("X-Tenant-ID",OTHER);Map<String,String> params=Map.of("type","router","status","unknown","site_id","site-a","q","literal%_","page_size","10");params.forEach(r::addParameter);var first=data(controller.assets(params,r));assertEquals(10,((List<?>)first.get("items")).size());assertEquals(true,first.get("has_more"));String cursor=(String)first.get("next_cursor");var nextQuery=new AssetReadQuery("router","unknown","site-a","literal%_",11,asset(10).createdAt(),asset(10).id());when(repository.authorizedAssets(TENANT,ACTOR,7,nextQuery)).thenReturn(List.of(asset(11)));Map<String,String> next=new HashMap<>(params);next.put("cursor",cursor);var nextRequest=request();next.forEach(nextRequest::addParameter);assertEquals(false,data(controller.assets(next,nextRequest)).get("has_more"));verify(repository).authorizedAssets(TENANT,ACTOR,7,query);verify(repository).authorizedAssets(TENANT,ACTOR,7,nextQuery);verify(repository,never()).list(any());verify(repository,never()).find(any(),any());}
    @Test void signedCursorRemainsBoundToFiltersTenantActorAndPermissionVersion(){String cursor=firstCursor();for(var params:List.of(Map.of("cursor",cursor,"q","other"),Map.of("cursor",cursor+"tampered"))){var r=request();params.forEach(r::addParameter);assertEquals("CURSOR_INVALID",assertThrows(DomainException.class,()->controller.assets(params,r)).code);}when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"msp",8,true)));assertEquals("CURSOR_INVALID",assertThrows(DomainException.class,()->controller.assets(Map.of("cursor",cursor),request())).code);when(repository.membership(ACTOR,OTHER)).thenReturn(Optional.of(new Membership(ACTOR,OTHER,"msp",7,true)));when(repository.tenant(OTHER)).thenReturn(new Tenant(OTHER,"Other"));var foreign=request();foreign.getSession().setAttribute("mop.tenant_id",OTHER);assertEquals("CURSOR_INVALID",assertThrows(DomainException.class,()->controller.assets(Map.of("cursor",cursor),foreign)).code);String actor2="55000000-0000-4000-8000-000000000002";when(repository.membership(actor2,TENANT)).thenReturn(Optional.of(new Membership(actor2,TENANT,"msp",7,true)));when(repository.user(actor2)).thenReturn(Optional.of(new FixtureUser(actor2,"Other actor","msp")));var another=request();another.setUserPrincipal(()->actor2);assertEquals("CURSOR_INVALID",assertThrows(DomainException.class,()->controller.assets(Map.of("cursor",cursor),another)).code);}
    @Test void detailUsesFreshAuthorizedLookupAndStillHidesUnknownObjects(){Asset value=asset(1);when(repository.authorizedAsset(TENANT,ACTOR,7,value.id())).thenReturn(Optional.of(value));assertEquals(value,((Map<?,?>)controller.asset(value.id(),request())).get("data"));when(repository.authorizedAsset(TENANT,ACTOR,7,"missing")).thenReturn(Optional.empty());assertEquals(404,assertThrows(DomainException.class,()->controller.asset("missing",request())).status);verify(repository,never()).find(any(),any());}
    @Test void malformedFiltersAndDuplicateParamsNeverReachTheReader(){for(var params:List.of(Map.of("tenant_id",OTHER),Map.of("q","x\u0000"),Map.of("q","\ud800"),Map.of("page_size","500"),Map.of("type","unrecognized"))){var r=request();params.forEach(r::addParameter);assertEquals(400,assertThrows(DomainException.class,()->controller.assets(params,r)).status);}var duplicate=request();duplicate.addParameter("page_size",new String[]{"10","15"});assertEquals(400,assertThrows(DomainException.class,()->controller.assets(Map.of("page_size","10"),duplicate)).status);verify(repository,never()).authorizedAssets(any(),any(),anyLong(),any());}
    @Test void revokedUnknownAndMalformedSessionScopeFailClosedBeforeReads(){when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"msp",7,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.assets(Map.of(),request())).status);when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"unknown",7,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.assets(Map.of(),request())).status);var malformed=request();malformed.getSession().setAttribute("mop.tenant_id",17);assertEquals(401,assertThrows(DomainException.class,()->controller.assets(Map.of(),malformed)).status);verify(repository,never()).authorizedAssets(any(),any(),anyLong(),any());}
}
